/* Interactive concept: uploads stay in browser; this does not generate or transfer garments. */
class AiStudio extends HTMLElement {
  constructor(){super();this.attachShadow({mode:'open'});this.file=null;this.fileUrl=null;this.uploadId=0;this.model='lia';this.scene='studio';this.models=[{id:'lia',name:'Lia',caption:'Editorial · pose livre',image:'assets/studio-model-1.jpg'},{id:'noah',name:'Noah',caption:'Casual · retrato próximo',image:'assets/studio-model-2.jpg'},{id:'maya',name:'Maya',caption:'Urbano · movimento',image:'assets/studio-model-3.jpg'}];this.scenes=[{id:'studio',name:'Estúdio claro',label:'Luz suave, fundo neutro',color:'#ece7df'},{id:'street',name:'Na rua',label:'Natural, com atitude',color:'#c7c9bd'},{id:'editorial',name:'Editorial',label:'Fundo lilás, luz marcada',color:'#d6c9e8'}]}
  connectedCallback(){this.render();this.bind()}
  disconnectedCallback(){if(this.fileUrl)URL.revokeObjectURL(this.fileUrl)}
  render(){this.shadowRoot.innerHTML=`<style>
:host{display:block;color:#29242e;font-family:'DM Sans',sans-serif;--purple:#6425d4;--muted:#827a89}*{box-sizing:border-box}button,input{font:inherit}button{cursor:pointer}button:focus-visible,a:focus-visible{outline:3px solid #9861ed;outline-offset:4px}.studio{display:grid;grid-template-columns:1fr 1.12fr;border:1px solid #e0d9e8;border-radius:18px;background:#fff;overflow:hidden;box-shadow:0 20px 60px #39264b08}.controls{padding:30px;border-right:1px solid #e8e2ed}.step{display:flex;align-items:center;gap:9px;font-size:12px;font-weight:650;margin:0 0 13px}.step>span{display:grid;place-items:center;width:23px;height:23px;border-radius:50%;background:#f1eafb;color:var(--purple);font-size:10px}.upload{position:relative;border:1px dashed #c9b7df;background:#fbf9fe;border-radius:10px;min-height:124px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:7px;text-align:center;padding:20px;transition:.2s}.upload.drag{border-color:var(--purple);background:#eee4fd}.upload svg{width:25px;height:25px;color:var(--purple)}.upload strong{font-size:12px;font-weight:600}.upload small{font-size:10px;color:var(--muted)}.upload input{position:absolute;inset:0;opacity:0;width:100%;height:100%;cursor:pointer}.upload:focus-within{outline:3px solid #9861ed;outline-offset:3px}.file-row{display:flex;align-items:center;gap:10px;padding:10px 12px;background:#f5f0fa;border-radius:8px;margin-top:10px}.file-row[hidden]{display:none}.file-row img{height:40px;width:40px;object-fit:contain;background:white;border-radius:5px}.file-info{min-width:0;flex:1}.file-info strong{display:block;font-size:10px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.file-info small{font-size:9px;color:var(--muted)}.remove{border:0;background:none;font-size:20px;color:#6e627b;width:27px;height:27px}.error{font-size:11px;line-height:1.5;color:#b03243;margin:8px 0 0}.error:empty{display:none}.control-block{margin-top:24px}.model-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:9px}.model-card{padding:0;background:#fff;border:1px solid #e2dce8;border-radius:8px;text-align:left;overflow:hidden;position:relative}.model-card.selected{border:2px solid var(--purple)}.model-card img{height:105px;width:100%;object-fit:cover;display:block;background:#e7e0ec}.model-card[data-model=lia] img{object-position:50% 28%}.model-card[data-model=noah] img{object-position:50% 18%}.model-card[data-model=maya] img{object-position:50% 25%}.model-card strong{display:block;font-size:11px;padding:8px 8px 2px}.model-card small{font-size:8px;color:var(--muted);display:block;padding:0 8px 9px;line-height:1.3}.check{position:absolute;top:7px;right:7px;width:17px;height:17px;border-radius:50%;display:grid;place-items:center;background:var(--purple);color:white;font-size:10px}.model-card:not(.selected) .check{display:none}.scene-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.scene{display:flex;align-items:center;gap:7px;border:1px solid #e2dce8;background:white;padding:11px 8px;border-radius:7px;font-size:9px;line-height:1.3;min-height:42px}.scene.selected{background:#f3edfd;border-color:var(--purple);color:var(--purple);font-weight:600}.scene i{width:13px;height:13px;display:block;flex:none;border-radius:50%;border:1px solid #0001}.guidance{font-size:10px;color:var(--muted);line-height:1.7;margin:16px 0 0}.preview-area{padding:26px;background:#f7f5f9;display:flex;flex-direction:column}.preview-top{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:15px}.preview-title{font-size:11px;font-weight:600}.preview-badge{font-size:8px;letter-spacing:.8px;border:1px solid #d8cde4;background:#eee8f4;padding:5px 7px;border-radius:4px;color:#786487}.visual{position:relative;min-height:310px;flex:1;overflow:hidden;border-radius:10px;background:#ece7df;display:grid;grid-template-columns:1.9fr 1fr;gap:13px;padding:18px;transition:background .25s}.reference{position:relative;min-height:280px;overflow:hidden;border-radius:7px;background:#dbd2c9}.reference>img{position:absolute;width:100%;height:100%;object-fit:cover;object-position:center 28%;inset:0}.ref-label{position:absolute;left:10px;top:10px;font-size:7px;color:white;background:#26212abf;padding:5px 6px;letter-spacing:1px;z-index:1}.reference:after{content:'';position:absolute;inset:55% 0 0;background:linear-gradient(transparent,#15101d88)}.ref-name{position:absolute;left:13px;bottom:12px;color:white;z-index:1}.ref-name strong{font-family:'Space Grotesk',sans-serif;font-size:24px;font-weight:500;letter-spacing:-1px;display:block}.ref-name small{font-size:8px;opacity:.8}.garment-side{display:flex;flex-direction:column;justify-content:center;gap:12px}.garment{border:1px solid #ffffffc9;background:#fff9;border-radius:7px;min-height:145px;position:relative;display:flex;align-items:center;justify-content:center;padding:12px}.garment img{width:100%;height:135px;object-fit:contain}.garment img[hidden]{display:none}.garment svg{width:42px;height:42px;stroke:#a99ab7;stroke-width:1.3;fill:none}.garment svg[hidden]{display:none}.garment-label{position:absolute;bottom:7px;text-align:center;font-size:7px;letter-spacing:.5px;color:#7d708a}.arrow{font-size:22px;color:#887592;text-align:center}.composition-note{font-size:8px;line-height:1.7;color:#6d5c77;text-align:center;margin:0}.visual-foot{display:flex;align-items:center;justify-content:space-between;margin:13px 0 18px;font-size:9px;color:var(--muted)}.visual-foot strong{color:#5e5069;font-weight:500}.status{display:flex;align-items:flex-start;gap:9px;padding:12px 0;border-top:1px solid #e0d8e7;font-size:10px;line-height:1.65;color:#786d82}.status svg{flex:none;width:15px;height:15px;stroke:var(--purple);margin-top:2px;fill:none;stroke-width:1.5}.status strong{font-weight:600;color:#51405e}.action{display:flex;justify-content:space-between;align-items:center;gap:18px;padding:14px 18px;border:0;border-radius:7px;background:var(--purple);color:white;font-weight:600;font-size:11px;margin-top:auto;width:100%}.action:disabled{cursor:not-allowed;background:#d9d1e3;color:#84768e}.action:not(:disabled):hover{background:#4e17af}.action span{font-size:19px}.feedback{font-size:10px;line-height:1.5;color:var(--purple);margin:10px 0 0;min-height:15px}.note-bottom{margin:9px 0 0;color:var(--muted);font-size:9px;line-height:1.6}.scene-note{display:block;margin-top:3px}.checklist{margin:0;padding:0;display:flex;list-style:none;gap:12px;flex-wrap:wrap;font-size:8px;color:#8a7e92}.checklist li:before{content:'✓';color:var(--purple);margin-right:4px}@media(max-width:900px){.controls{padding:22px}.preview-area{padding:20px}.model-card img{height:85px}.visual{padding:12px;gap:9px;min-height:300px}.reference{min-height:270px}.scene-grid{gap:5px}.scene{padding:8px 5px;font-size:8px}.garment{padding:7px}.garment img{height:110px}.composition-note{font-size:7px}}@media(max-width:650px){.studio{grid-template-columns:1fr;border-radius:12px}.controls{padding:22px;border-right:0;border-bottom:1px solid #e8e2ed}.preview-area{padding:22px}.model-card img{height:130px}.model-card strong{font-size:12px}.model-card small{font-size:9px}.scene{font-size:10px;padding:12px 8px}.visual{min-height:350px;grid-template-columns:1.65fr 1fr;padding:15px;gap:13px}.reference{min-height:320px}.garment img{height:145px}.composition-note{font-size:9px}.preview-badge{font-size:7px}.visual-foot{font-size:8px}.status{margin-top:1px}.action{margin-top:8px}}
</style><section class="studio" aria-label="Estúdio de fotos: conceito interativo"><div class="controls"><p class="step"><span>1</span> A peça começa com uma boa foto.</p><label class="upload"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M12 16V4m-4 4 4-4 4 4M4 15v5h16v-5"/></svg><strong>Escolha ou arraste sua foto</strong><small>JPG, PNG ou WebP · até 8 MB</small><input type="file" accept="image/jpeg,image/png,image/webp" aria-label="Selecionar foto da roupa"></label><div class="file-row" hidden><img alt="Prévia da roupa enviada"><div class="file-info"><strong></strong><small></small></div><button class="remove" aria-label="Remover foto da roupa">×</button></div><p class="error" role="alert"></p><div class="control-block"><p class="step"><span>2</span> Escolha uma referência de modelo.</p><div class="model-grid">${this.models.map(m=>`<button class="model-card ${m.id===this.model?'selected':''}" data-model="${m.id}" aria-pressed="${m.id===this.model}"><img src="${m.image}" alt="Referência visual ${m.name}" loading="lazy"><span class="check">✓</span><strong>${m.name}</strong><small>${m.caption}</small></button>`).join('')}</div></div><div class="control-block"><p class="step"><span>3</span> O cenário também conta sua história.</p><div class="scene-grid">${this.scenes.map(s=>`<button class="scene ${s.id===this.scene?'selected':''}" data-scene="${s.id}" aria-pressed="${s.id===this.scene}"><i style="background:${s.color}"></i>${s.name}</button>`).join('')}</div></div><p class="guidance">Fotografe a peça de frente, bem iluminada e sem dobras. A foto fica apenas neste navegador.</p></div><div class="preview-area"><div class="preview-top"><span class="preview-title">Direção do seu próximo ensaio</span><span class="preview-badge">PRÉVIA DE REFERÊNCIAS</span></div><div class="visual"><div class="reference"><img id="model-preview" src="${this.models[0].image}" alt="Foto de referência da modelo Lia"><span class="ref-label">REFERÊNCIA VISUAL</span><div class="ref-name"><strong>Lia</strong><small>Editorial · pose livre</small></div></div><div class="garment-side"><div class="garment"><img id="garment-preview" alt="Sua roupa enviada" hidden><svg id="garment-placeholder" viewBox="0 0 48 48"><path d="m16 8-10 6 5 10 5-3v20h16V21l5 3 5-10-10-6c0 8-16 8-16 0Z"/></svg><span class="garment-label">SUA PEÇA</span></div><div class="arrow">↗</div><p class="composition-note">Sua roupa +<br>sua direção criativa.</p></div></div><div class="visual-foot"><span><strong id="scene-name">Estúdio claro</strong><span class="scene-note" id="scene-note">Luz suave, fundo neutro</span></span><ul class="checklist"><li>Sua peça</li><li>Seu estilo</li></ul></div><div class="status"><svg viewBox="0 0 20 20"><circle cx="10" cy="10" r="7.5"/><path d="M10 8v5m0-8v1"/></svg><div><strong>O ensaio com IA vem na próxima etapa.</strong><br>Estas são referências fotográficas, não resultados gerados. Neste protótipo, a roupa ainda não é aplicada ao modelo.</div></div><button class="action" id="download" disabled>Baixar direção do ensaio <span>↗</span></button><p class="feedback" role="status"></p><p class="note-bottom">Um arquivo com suas escolhas, pronto para orientar a produção. Sem envio de fotos ou cobrança.</p></div></section>`}
  bind(){const r=this.shadowRoot;this.q=s=>r.querySelector(s);const input=this.q('input[type=file]');input.addEventListener('change',()=>{if(input.files[0])this.setFile(input.files[0])});const zone=this.q('.upload');for(const type of ['dragenter','dragover'])zone.addEventListener(type,e=>{e.preventDefault();zone.classList.add('drag')});for(const type of ['dragleave','drop'])zone.addEventListener(type,e=>{e.preventDefault();zone.classList.remove('drag')});zone.addEventListener('drop',e=>{if(e.dataTransfer.files.length>1){this.showError('Escolha uma foto por vez para preparar o ensaio.');return}if(e.dataTransfer.files[0])this.setFile(e.dataTransfer.files[0])});this.q('.remove').addEventListener('click',()=>this.clearFile());r.querySelectorAll('[data-model]').forEach(b=>b.addEventListener('click',()=>{this.model=b.dataset.model;r.querySelectorAll('[data-model]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',x===b)});const model=this.models.find(m=>m.id===this.model);this.q('#model-preview').src=model.image;this.q('#model-preview').alt=`Foto de referência ${model.name}`;this.q('.ref-name strong').textContent=model.name;this.q('.ref-name small').textContent=model.caption;this.q('.feedback').textContent=''}));r.querySelectorAll('[data-scene]').forEach(b=>b.addEventListener('click',()=>{this.scene=b.dataset.scene;r.querySelectorAll('[data-scene]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',x===b)});const scene=this.scenes.find(s=>s.id===this.scene);this.q('.visual').style.background=scene.color;this.q('#scene-name').textContent=scene.name;this.q('#scene-note').textContent=scene.label;this.q('.feedback').textContent=''}));this.q('#download').addEventListener('click',()=>this.download())}
  showError(text){this.q('.error').textContent=text}
  setFile(file){const uploadId=++this.uploadId;this.showError('');this.q('.feedback').textContent='';if(!['image/jpeg','image/png','image/webp'].includes(file.type)){this.showError('Esse formato não é aceito. Escolha uma imagem JPG, PNG ou WebP.');return}if(file.size>8*1024*1024){this.showError('Sua foto passou de 8 MB. Escolha uma imagem menor.');return}if(!file.size){this.showError('O arquivo está vazio. Escolha outra foto.');return}const url=URL.createObjectURL(file);const image=new Image();image.onload=()=>{if(uploadId!==this.uploadId){URL.revokeObjectURL(url);return}if(this.fileUrl)URL.revokeObjectURL(this.fileUrl);this.file=file;this.fileUrl=url;this.dimensions={width:image.naturalWidth,height:image.naturalHeight};this.q('.file-row').hidden=false;this.q('.file-row img').src=url;this.q('.file-info strong').textContent=file.name;this.q('.file-info small').textContent=`${(file.size/1024/1024).toFixed(1)} MB · ${image.naturalWidth} × ${image.naturalHeight}`;this.q('#garment-preview').src=url;this.q('#garment-preview').hidden=false;this.q('#garment-placeholder').setAttribute('hidden','');this.q('#download').disabled=false;this.q('.feedback').textContent='Foto pronta. Escolha as referências e baixe a direção do ensaio.'};image.onerror=()=>{URL.revokeObjectURL(url);if(uploadId!==this.uploadId)return;this.showError('Não foi possível abrir essa imagem. Tente outra foto.')};image.src=url}
  clearFile(){this.uploadId++;if(this.fileUrl)URL.revokeObjectURL(this.fileUrl);this.file=null;this.fileUrl=null;this.q('input[type=file]').value='';this.q('.file-row').hidden=true;this.q('#garment-preview').hidden=true;this.q('#garment-preview').removeAttribute('src');this.q('#garment-placeholder').removeAttribute('hidden');this.q('#download').disabled=true;this.q('.feedback').textContent='';this.showError('')}
  download(){if(!this.file)return;const model=this.models.find(m=>m.id===this.model),scene=this.scenes.find(s=>s.id===this.scene);const brief={projeto:'Camizetas — direção de ensaio',versao:1,tipo:'briefing de demonstração — sem geração de imagem',modelo:{id:model.id,nome:model.name,direcao:model.caption,referenciaFotografica:model.image},cenario:{id:scene.id,nome:scene.name,direcao:scene.label},peca:{arquivo:this.file.name,tipo:this.file.type,tamanhoBytes:this.file.size,dimensoes:this.dimensions},observacoes:['A foto permanece no navegador e não está incluída neste arquivo.','As fotos dos modelos são referências visuais; não são imagens geradas por IA.','A transferência da peça ao modelo ainda depende de integração e revisão da fidelidade visual.']};const url=URL.createObjectURL(new Blob([JSON.stringify(brief,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download='camizetas-direcao-do-ensaio.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);this.q('.feedback').textContent='Direção do ensaio baixada. Sua foto continua só neste navegador.'}
}
if(!customElements.get('ai-studio'))customElements.define('ai-studio',AiStudio);
